import React, { useState, useEffect } from 'react';

const API = 'http://localhost:5000/api';

function GameList({ user }) {
  const [games, setGames] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');

  useEffect(() => {
    fetchGames();
  }, [search]);

  const fetchGames = async () => {
    setLoading(true);
    try {
      const params = search ? `?search=${search}` : '';
      const res = await fetch(`${API}/games${params}`);
      const data = await res.json();
      setGames(Array.isArray(data) ? data : data.games || []);
    } catch {
      setGames([]);
    }
    setLoading(false);
  };

  return (
    <div>
      <h2 style={heading}>Game Catalog</h2>
      <input
        style={searchInput}
        placeholder="Search games..."
        value={search}
        onChange={e => setSearch(e.target.value)}
      />
      {loading ? <p style={{ color: '#aaa' }}>Loading...</p> : (
        <table style={table}>
          <thead>
            <tr>
              {['Title', 'Platform', 'Genre', 'Rent/day', 'Buy Price'].map(h => (
                <th key={h} style={th}>{h}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {games.length === 0 ? (
              <tr><td colSpan={5} style={{ ...td, color: '#aaa', textAlign: 'center' }}>No games found</td></tr>
            ) : games.map((g, i) => (
              <tr key={g.gameID || i}>
                <td style={td}>{g.title || g.name}</td>
                <td style={td}>{g.platform || '—'}</td>
                <td style={td}>{g.genre || '—'}</td>
                <td style={{ ...td, color: '#00ff88' }}>{g.rentalPrice ? `$${Number(g.rentalPrice).toFixed(2)}` : '—'}</td>
                <td style={{ ...td, color: '#00ff88' }}>{g.purchasePrice ? `$${Number(g.purchasePrice).toFixed(2)}` : '—'}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}

const heading = { color: '#fff', marginBottom: '1rem', fontFamily: 'sans-serif' };
const searchInput = {
  marginBottom: '1rem', padding: '0.6rem 1rem', width: '100%', maxWidth: 400,
  background: '#1a1a2e', border: '1px solid #333', borderRadius: 8, color: '#fff', fontSize: '0.9rem'
};
const table = { width: '100%', borderCollapse: 'collapse' };
const th = { textAlign: 'left', padding: '0.75rem 1rem', color: '#aaa', fontSize: '0.8rem', borderBottom: '1px solid #333', textTransform: 'uppercase' };
const td = { padding: '0.75rem 1rem', color: '#ccc', borderBottom: '1px solid #222', fontSize: '0.9rem' };

export default GameList;
